#include <iostream>
#include <vector>
#include <algorithm>
#include <numeric>     // accumulate
#include <cmath>       // sqrt, pow
#include <map>
#include <iomanip>     // setprecision
using namespace std;

double mean(const vector<int>& v) {
    return accumulate(v.begin(), v.end(), 0.0) / v.size();
}

double median(vector<int> v) {                 // copy, so the original is unchanged
    sort(v.begin(), v.end());
    int n = v.size();
    if (n % 2 == 1) return v[n / 2];
    return (v[n / 2 - 1] + v[n / 2]) / 2.0;
}

vector<int> modes(const vector<int>& v) {
    map<int, int> freq;
    for (int x : v) freq[x]++;
    int best = 0;
    for (auto& p : freq) best = max(best, p.second);
    vector<int> result;
    if (best == 1) return result;              // no value repeats: no mode
    for (auto& p : freq) if (p.second == best) result.push_back(p.first);
    return result;
}

int rangeOf(const vector<int>& v) {
    auto [mn, mx] = minmax_element(v.begin(), v.end());
    return *mx - *mn;
}

double stdDev(const vector<int>& v) {
    double m = mean(v), sumSq = 0;
    for (int x : v) sumSq += pow(x - m, 2);
    return sqrt(sumSq / v.size());
}

int main() {
    vector<int> marks = {45, 67, 82, 67, 90, 55, 73, 67, 88, 60};
    cout << fixed << setprecision(2);
    cout << "Mean     : " << mean(marks) << endl;
    cout << "Median   : " << median(marks) << endl;
    cout << "Mode     : ";
    for (int m : modes(marks)) cout << m << " ";
    cout << endl;
    cout << "Range    : " << rangeOf(marks) << endl;
    cout << "Std. dev.: " << stdDev(marks) << endl;
    return 0;
}

#include <iostream>
#include <vector>
#include <map>
#include <string>
using namespace std;

char grade(int m) {
    if (m >= 90) return 'A';
    if (m >= 75) return 'B';
    if (m >= 60) return 'C';
    if (m >= 33) return 'D';
    return 'F';
}

int main() {
    vector<int> marks = {45, 67, 82, 67, 90, 55, 73, 67, 88, 60};
    map<char, int> freq = {{'A',0},{'B',0},{'C',0},{'D',0},{'F',0}};
    for (int m : marks) freq[grade(m)]++;

    cout << "Grade  Count  Chart" << endl;
    for (auto& p : freq)
        cout << "  " << p.first << "      " << p.second << "    " <<
string(p.second, '*') << endl;
    return 0;
}

#include <iostream>
#include <vector>
#include <string>
#include <stdexcept>
using namespace std;

int main() {
    vector<string> raw = {"85", "8 5", "", "105", "72", "abc", "64"};
    vector<int> clean;
    for (const string& s : raw) {
        try {
            size_t used;
            int v = stoi(s, &used);                     // throws for "" and "abc"
            if (used != s.size()) throw invalid_argument("extra characters");
            if (v < 0 || v > 100) throw out_of_range("not between 0 and 100");
            clean.push_back(v);
        }
        catch (const exception& e) {
            cout << "Rejected \"" << s << "\"" << endl;
        }
    }
    double sum = 0;
    for (int v : clean) sum += v;
    cout << "Valid values: " << clean.size() << ", mean = " << sum /
clean.size() << endl;
    return 0;
}

