#include <iostream>
#include <fstream>
#include <sstream>
#include <string>
using namespace std;

int main() {
    ifstream fin("opd.csv");
    string line, day, num, busiestDay;
    getline(fin, line);                          // skip header
    int total = 0, n = 0, busiest = -1;
    while (getline(fin, line)) {
        stringstream ss(line);
        getline(ss, day, ',');
        getline(ss, num, ',');
        int p = stoi(num);
        total += p; n++;
        if (p > busiest) { busiest = p; busiestDay = day; }
    }
    cout << "Total patients: " << total << endl;
    cout << "Average per day: " << (double)total / n << endl;
    cout << "Busiest day: " << busiestDay << " (" << busiest << ")" << endl;
    return 0;
}
